const IDENTITY_FACT_TYPES = [
  "Pronouns", "Gender Identity", "Gender Expression", "Sexual Orientation", "Romantic Orientation", "Relationship Orientation",
  "LGBTQIA2+ Identity", "2SLGBTQIA+ Identity", "Hypersexuality", "Sexuality Note", "Identity Label",
  "Alterhuman Identity", "Alterhuman Branch", "Kintype", "Theriotype", "Otherkin Identity", "Therian Identity",
  "Polytherian Identity", "Phytanthropy", "Phytanthrope", "Phytotherian", "Plantkin"
];

const PHYSICAL_FACT_TYPES = ["Medical Condition", "Diagnosis", "Diagnosis criteria", "Physical condition", "Chronic condition", "Degenerative condition", "Rare disease", "Pain condition", "Trauma-related condition", "Neurological condition", "Developmental condition"];
const DISABILITY_FACT_TYPES = ["Disability or Access Need", "Mobility Aid", "Assistive Technology", "Physical disability", "Sensory disability", "Mobility disability", "Neurological disability", "Developmental disability", "Cognitive disability", "Communication disability", "Functional limitation", "Health support need", "Access accommodation"];

export const SENSITIVE_FACT_TYPES = new Set(["Religion", "Belief", "Religious practice", "Mental health condition", "Mental health support need", ...PHYSICAL_FACT_TYPES, ...DISABILITY_FACT_TYPES, ...IDENTITY_FACT_TYPES]);

export function isSensitiveFactType(type: string): boolean {
  return SENSITIVE_FACT_TYPES.has(type);
}

export function catalogForFactType(type: string, customTerms: readonly { category: string; term: string; meaning: string }[] = []): readonly PersonFactCatalogEntry[] | undefined {
  const builtIn = type === "Religion" ? RELIGION_OPTIONS
    : type === "Belief" ? BELIEF_OPTIONS
      : type === "Religious practice" ? RELIGIOUS_PRACTICE_OPTIONS
        : type === "Mental health condition" ? MENTAL_HEALTH_OPTIONS
          : type === "Mental health support need" ? MENTAL_HEALTH_SUPPORT_OPTIONS
          : ["Degenerative condition"].includes(type) ? [...DEGENERATIVE_CONDITION_OPTIONS, ...PHYSICAL_CONDITION_OPTIONS.filter(entry => ["Parkinson's disease", "Multiple sclerosis (MS)", "Muscular dystrophy", "Osteoarthritis"].includes(entry.label))]
            : PHYSICAL_FACT_TYPES.includes(type) ? [...PHYSICAL_CONDITION_OPTIONS, ...DEGENERATIVE_CONDITION_OPTIONS]
                : ["Mobility Aid", "Assistive Technology", "Health support need", "Access accommodation"].includes(type) ? ACCESSIBILITY_AID_OPTIONS
                : DISABILITY_FACT_TYPES.includes(type) ? DISABILITY_CONDITION_OPTIONS
                : IDENTITY_FACT_TYPES.includes(type) ? IDENTITY_OPTIONS
                  : undefined;
  if (!builtIn) return undefined;
  const custom = customTerms.filter(entry => entry.category === type
    || (entry.category === "Identity, sexuality, or gender" && IDENTITY_FACT_TYPES.includes(type))
    || (entry.category === "Physical condition" && PHYSICAL_FACT_TYPES.includes(type))
    || (entry.category === "Disability or access need" && DISABILITY_FACT_TYPES.includes(type))
    || (entry.category === "Medical or diagnostic term" && [...PHYSICAL_FACT_TYPES, ...DISABILITY_FACT_TYPES, "Mental health condition", "Mental health support need"].includes(type))
  ).map(entry => ({ label: entry.term, meaning: entry.meaning }));
  return custom.length ? [...builtIn, ...custom] : builtIn;
}

export function catalogMeaning(type: string, value: string, customTerms: readonly { category: string; term: string; meaning: string }[] = []): string | undefined {
  return catalogForFactType(type, customTerms)?.find(entry => entry.label === value || entry.aliases?.includes(value))?.meaning;
}

export function catalogCriteria(type: string, value: string, customTerms: readonly { category: string; term: string; meaning: string }[] = []): string | undefined {
  const entry = catalogForFactType(type, customTerms)?.find(entry => entry.label === value || entry.aliases?.includes(value));
  if (entry?.criteria) return entry.criteria;
  if (type === "Mental health condition") return "Record the exact diagnosis date, diagnosing clinician, diagnostic standard used, duration/signs noted in the source, functional impact, risk/safety notes if relevant, and attached assessment files. KinForge does not diagnose.";
  if (type === "Mental health support need") return "Record the support need, who recommended it, date, setting, accommodations, crisis/safety plan if any, and privacy.";
  if (PHYSICAL_FACT_TYPES.includes(type)) return "Record diagnosis date, clinician, hospital or clinic, diagnostic criteria or tests used, symptoms, functional impact, treatment, and files. KinForge stores the source; it does not diagnose.";
  if (DISABILITY_FACT_TYPES.includes(type)) return "Record the person's preferred wording, barriers, functional impact, assistive devices, accommodations, support people, and privacy. Do not infer a diagnosis from an access need.";
  return undefined;
}
